'use client';

import * as React from 'react';

// @interlace/word-cloud v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/word-cloud
// What changed since: https://ds.interlace.tools/c/word-cloud#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — WordCloud and WordEntry
 *
 * The room's words, live. Phones send a word or two with `WordEntry`; the
 * shared screen shows them as a `WordCloud` in which the words the room
 * repeats grow, the biggest sit in the middle, and every change moves into
 * place rather than jumping there. Anyone in the room sees their voice land
 * within a second, without their name on it.
 *
 * ## Anatomy
 *
 *   WordCloud                       (div — data-slot="word-cloud", @container)
 *     ├─ ul (FlipGroup)             (data-slot="word-cloud-list", rank order in the DOM)
 *     │    ├─ li × n                (data-slot="word-cloud-word", data-step=1…5, data-band, data-mine, data-top)
 *     │    └─ li × 2                (data-slot="word-cloud-break": hidden line breaks between the bands)
 *     └─ p aria-live               (data-slot="word-cloud-status": "12 words from the room", or the empty text)
 *
 *   WordEntry                       (form — data-slot="word-entry")
 *     ├─ label + Input + Button     (data-slot="word-entry-field")
 *     ├─ p aria-live               (data-slot="word-entry-message": why a word was refused, or how many are left)
 *     └─ ul                         (data-slot="word-entry-sent": the viewer's own words, as chips)
 *
 * ## Data
 *
 * `WordCloud` takes `entries` (what was typed, and by whom) and builds the
 * cloud with `buildCloud` from `word-cloud-model`, or a prebuilt `words`
 * list from a server. `WordEntry` checks each word with `checkText` from
 * `text-safety-model` before `onWord` fires, so a refused word never leaves
 * the phone; run the same check on the server, which is the one that counts.
 * Pass your room's `blocklist` to both.
 *
 * ## Motion
 *
 * The list is a FlipGroup: when a word climbs, it and its neighbours glide
 * to their new places (400ms, `--ease-move`), and a new word scales up from
 * where it lands. A word whose count went up gives one small pulse
 * (`transform` only, 250ms), so the eye finds what just changed. Under
 * reduced motion every word simply takes its place.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                     |
 * | ---- | ------------------------- | ------------------------------------------------------ |
 * | R4   | Extends native el         | `div` / `form` props                                   |
 * | R6   | data-slot per part        | word-cloud / -list / -word / -status, word-entry / …   |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                      |
 * | R9   | Controlled + uncontrolled | WordEntry `sent` / `defaultSent` / `onWord`            |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                   |
 * | R26  | A11y                      | list in rank order, each word with its count; refusals announced |
 */

import { FlipGroup } from '@/components/ui/effects/flip-group';
import { cn } from '@/lib/utils';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { checkText, type TextRefusal, type TextRules } from '@/components/ui/games/text-safety-model';
import {
  buildCloud,
  CLOUD_BREAKS,
  cloudOrder,
  type CloudEntry,
  type CloudOptions,
  type CloudWord,
} from '@/components/ui/games/word-cloud-model';

export const MIN_VIEWPORT = 320 as const;

// --- WordCloud ------------------------------------------------------------------

interface WordCloudLabels {
  /** Read with each word. @default (word, count) => `${word}, ${count}` */
  word?: (text: string, count: number, formatted: string) => string;
  /** Under the cloud. @default (total, formatted) => `${formatted} ${total === 1 ? 'word' : 'words'} from the room` */
  status?: (total: number, formatted: string) => string;
  /** While nothing has been sent. @default 'Words appear here as people send them.' */
  empty?: string;
  /** Marks the viewer's own words for screen readers. @default 'yours' */
  mine?: string;
}

type WordCloudProps = Omit<React.ComponentProps<'div'>, 'children'> &
  Pick<CloudOptions, 'max' | 'stopwords' | 'viewer'> & {
    /** What the room sent. Ignored when `words` is given. */
    entries?: readonly (CloudEntry | string)[];
    /** A cloud already built (for example by a server with `buildCloud`). */
    words?: readonly CloudWord[];
    /** `stage` for a shared screen across a room, `default` for a page or a phone. @default 'default' */
    size?: 'default' | 'stage';
    locale?: string;
    labels?: WordCloudLabels;
  };

const STEP_CLASS: Record<'default' | 'stage', readonly string[]> = {
  default: ['text-sm', 'text-base', 'text-xl', 'text-3xl', 'text-5xl'],
  stage: ['text-lg', 'text-2xl', 'text-4xl', 'text-6xl', 'text-8xl'],
};
const WEIGHT = ['font-normal', 'font-normal', 'font-medium', 'font-semibold', 'font-bold'] as const;

function WordCloud({
  entries,
  words: wordsProp,
  max,
  stopwords,
  viewer,
  size = 'default',
  locale,
  labels,
  className,
  ...props
}: WordCloudProps) {
  const reduced = useReducedMotion();
  const listRef = React.useRef<HTMLDivElement>(null);
  const nf = React.useMemo(() => new Intl.NumberFormat(locale), [locale]);

  const cloud = React.useMemo(() => {
    if (wordsProp) {
      return { words: [...wordsProp], total: wordsProp.reduce((a, w) => a + w.count, 0) };
    }
    return buildCloud(entries ?? [], { max, stopwords, viewer });
  }, [wordsProp, entries, max, stopwords, viewer]);

  const places = React.useMemo(() => cloudOrder(cloud.words.length), [cloud.words.length]);

  // One pulse on each word whose count went up since the last render.
  const counts = React.useRef(new Map<string, number>());
  React.useEffect(() => {
    const prev = counts.current;
    const next = new Map(cloud.words.map((w) => [w.key, w.count]));
    counts.current = next;
    if (reduced || prev.size === 0) return;
    const root = listRef.current;
    if (!root) return;
    for (const w of cloud.words) {
      const before = prev.get(w.key);
      if (before === undefined || before >= w.count) continue;
      const el = root.querySelector<HTMLElement>(
        `[data-word-key="${CSS.escape(w.key)}"] [data-slot="word-cloud-text"]`,
      );
      if (!el || typeof el.animate !== 'function') continue;
      el.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.18)' }, { transform: 'scale(1)' }], {
        duration: 250,
        easing: 'cubic-bezier(0.16, 1, 0.3, 1)',
      });
    }
  }, [cloud.words, reduced]);

  const sizes = STEP_CLASS[size];

  return (
    <div
      data-slot="word-cloud"
      data-size={size}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('@container grid gap-4', className)}
      {...props}
    >
      <div ref={listRef}>
        <FlipGroup
          render={<ul />}
          data-slot="word-cloud-list"
          className={cn(
            'flex flex-wrap items-center justify-center gap-x-4 gap-y-1 text-center',
            size === 'stage' ? 'min-h-48 gap-x-8 gap-y-2' : 'min-h-32',
          )}
        >
          {cloud.words.map((w, i) => {
            const step = Math.min(sizes.length, Math.max(1, w.step)) - 1;
            const formatted = nf.format(w.count);
            const top = w.rank === 0 && cloud.words.length > 1;
            return (
              <li
                key={w.key}
                data-flip-id={w.key}
                data-word-key={w.key}
                data-slot="word-cloud-word"
                data-step={step + 1}
                data-top={top ? '' : undefined}
                data-mine={w.mine ? '' : undefined}
                data-band={places[i]?.band}
                style={{ order: places[i]?.order }}
                className="max-w-full leading-tight"
              >
                <span
                  data-slot="word-cloud-text"
                  aria-hidden
                  className={cn(
                    'inline-block break-words font-heading tracking-tight',
                    sizes[step],
                    WEIGHT[step],
                    top ? 'text-primary' : step <= 1 ? 'text-muted-foreground' : 'text-foreground',
                    w.mine && 'decoration-primary underline decoration-2 underline-offset-4',
                  )}
                >
                  {w.text}
                </span>
                <span className="sr-only">
                  {(labels?.word ?? ((t: string, _c: number, f: string) => `${t}, ${f}`))(w.text, w.count, formatted)}
                  {w.mine ? `, ${labels?.mine ?? 'yours'}` : ''}
                </span>
              </li>
            );
          })}
          {cloud.words.length > 1
            ? CLOUD_BREAKS.map((order) => (
                <li
                  key={`break-${order}`}
                  role="presentation"
                  aria-hidden
                  data-slot="word-cloud-break"
                  className="h-0 basis-full"
                  style={{ order }}
                />
              ))
            : null}
        </FlipGroup>
      </div>
      <p
        data-slot="word-cloud-status"
        aria-live="polite"
        className="text-muted-foreground text-center text-sm tabular-nums"
      >
        {cloud.total === 0
          ? (labels?.empty ?? 'Words appear here as people send them.')
          : (labels?.status ?? ((n: number, f: string) => `${f} ${n === 1 ? 'word' : 'words'} from the room`))(
              cloud.total,
              nf.format(cloud.total),
            )}
      </p>
    </div>
  );
}
WordCloud.displayName = 'WordCloud';

// --- WordEntry ------------------------------------------------------------------

interface WordEntryLabels {
  /** The field's label. @default 'Your word' */
  field?: string;
  /** The button. @default 'Send' */
  send?: string;
  /** How many are left. @default (n) => `You can send ${n} more.` */
  left?: (remaining: number) => string;
  /** When every word is sent. @default 'Thanks. Your words are on the screen.' */
  done?: string;
  /** The list of sent words. @default 'Your words' */
  sent?: string;
  /** Why a word was refused. */
  refused?: Partial<Record<TextRefusal | 'repeat', string>>;
}

type WordEntryProps = Omit<React.ComponentProps<'form'>, 'onSubmit' | 'children'> &
  Pick<TextRules, 'blocklist'> & {
    /** Words each person may send. @default 3 */
    maxWords?: number;
    /** The longest word or phrase, in characters. @default 25 */
    maxLength?: number;
    /** Words in one entry ("good food" is two). @default 2 */
    wordsPerEntry?: number;
    /** The words sent so far, controlled. */
    sent?: readonly string[];
    /** The words sent so far, uncontrolled. */
    defaultSent?: readonly string[];
    /** Called once per accepted word. */
    onWord?: (word: string) => void;
    /** No more words (for example when the host closes the round). */
    disabled?: boolean;
    placeholder?: string;
    labels?: WordEntryLabels;
  };

const REFUSED: Record<TextRefusal | 'repeat', string> = {
  empty: 'Type a word first.',
  'too-long': 'That is too long. Try a shorter word.',
  'too-many-words': 'One or two words, please.',
  link: 'Links cannot be sent here.',
  contact: 'Email addresses and phone numbers cannot be sent here.',
  blocked: 'That word cannot be shown here. Try another.',
  repeat: 'You already sent that one.',
};

function WordEntry({
  maxWords = 3,
  maxLength = 25,
  wordsPerEntry = 2,
  blocklist,
  sent: sentProp,
  defaultSent = [],
  onWord,
  disabled = false,
  placeholder,
  labels,
  className,
  ...props
}: WordEntryProps) {
  const [own, setOwn] = React.useState<readonly string[]>(defaultSent);
  const sent = sentProp ?? own;
  const [value, setValue] = React.useState('');
  const [refusal, setRefusal] = React.useState<TextRefusal | 'repeat' | null>(null);
  const inputId = React.useId();
  const messageId = React.useId();
  const remaining = Math.max(0, maxWords - sent.length);
  const closed = disabled || remaining === 0;

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (closed) return;
    const check = checkText(value, { maxLength, maxWords: wordsPerEntry, blocklist });
    if (!check.ok) {
      setRefusal(check.reason);
      return;
    }
    if (sent.some((s) => s.toLocaleLowerCase() === check.text.toLocaleLowerCase())) {
      setRefusal('repeat');
      return;
    }
    setRefusal(null);
    setValue('');
    if (sentProp === undefined) setOwn((prev) => [...prev, check.text]);
    onWord?.(check.text);
  };

  const message = refusal
    ? (labels?.refused?.[refusal] ?? REFUSED[refusal])
    : remaining === 0
      ? (labels?.done ?? 'Thanks. Your words are on the screen.')
      : sent.length > 0
        ? (labels?.left ?? ((n: number) => `You can send ${n} more.`))(remaining)
        : '';

  return (
    <form
      data-slot="word-entry"
      data-state={closed ? 'closed' : 'open'}
      data-min-viewport={String(MIN_VIEWPORT)}
      noValidate
      onSubmit={submit}
      className={cn('grid gap-3', className)}
      {...props}
    >
      <div data-slot="word-entry-field" className="grid gap-1.5">
        <label htmlFor={inputId} className="text-sm font-medium">
          {labels?.field ?? 'Your word'}
        </label>
        <div className="flex gap-2">
          <Input
            id={inputId}
            value={value}
            onChange={(e) => {
              setValue(e.target.value);
              if (refusal) setRefusal(null);
            }}
            placeholder={placeholder}
            disabled={closed}
            autoComplete="off"
            autoCapitalize="none"
            enterKeyHint="send"
            maxLength={maxLength * 2}
            aria-invalid={refusal ? true : undefined}
            aria-describedby={messageId}
            className="min-w-0 flex-1"
          />
          <Button type="submit" size="lg" disabled={closed}>
            {labels?.send ?? 'Send'}
          </Button>
        </div>
      </div>
      <p
        id={messageId}
        data-slot="word-entry-message"
        data-refused={refusal ?? undefined}
        aria-live="polite"
        className={cn('min-h-5 text-sm', refusal ? 'text-destructive' : 'text-muted-foreground')}
      >
        {message}
      </p>
      {sent.length > 0 ? (
        <ul data-slot="word-entry-sent" aria-label={labels?.sent ?? 'Your words'} className="flex flex-wrap gap-2">
          {sent.map((w) => (
            <li
              key={w}
              className="bg-primary/10 text-foreground motion-safe:animate-in motion-safe:zoom-in-90 motion-safe:duration-(--duration-base) motion-safe:ease-enter rounded-full px-3 py-1 text-sm font-medium"
            >
              {w}
            </li>
          ))}
        </ul>
      ) : null}
    </form>
  );
}
WordEntry.displayName = 'WordEntry';

export { WordCloud, WordEntry };
export type { WordCloudProps, WordCloudLabels, WordEntryProps, WordEntryLabels };

export type TextRefusal = 'empty' | 'too-long' | 'too-many-words' | 'link' | 'contact' | 'blocked';

export interface TextRules {
  /** The most characters, as the reader counts them. @default 200 */
  maxLength?: number;
  /** The most words. @default Infinity */
  maxWords?: number;
  /** Words the room refuses. Matched whole, after `foldText`. */
  blocklist?: readonly string[];
  /** Let links through. @default false */
  allowLinks?: boolean;
  /** Let email addresses and phone numbers through. @default false */
  allowContact?: boolean;
}

export type TextCheck = { ok: true; text: string } | { ok: false; reason: TextRefusal };

const SWAPS: Record<string, string> = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '@': 'a', $: 's' };

/** Trims, collapses runs of white space and applies Unicode NFC, so the same word typed twice is the same string. */
export function tidyText(input: string): string {
  return input.normalize('NFC').replace(/\s+/gu, ' ').trim();
}

/** How many characters a reader sees (grapheme clusters, so an emoji or a letter with marks counts once). */
export function visibleLength(text: string): number {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    let n = 0;
    for (const _ of new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)) n++;
    return n;
  }
  return Array.from(text).length;
}

/** Splits into words on white space. */
export function wordsOf(text: string): string[] {
  const t = tidyText(text);
  return t ? t.split(' ') : [];
}

/**
 * The form used for matching, never for showing: lowercase, no accents or
 * combining marks (Latin accents, Hebrew points, Arabic short vowels), the
 * common letter swaps folded, and spelled-out letters joined.
 */
export function foldText(input: string): string {
  const base = input
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[013457@$]/g, (c) => SWAPS[c] as string);
  // "b a d", "b.a.d", "b-a-d" → "bad": three or more single letters in a row.
  const joined = base.replace(
    /(?<![\p{L}\p{N}])\p{L}(?:[\s.\-_*]+\p{L})(?:[\s.\-_*]+\p{L})+(?![\p{L}\p{N}])/gu,
    (run) => run.replace(/[\s.\-_*]+/g, ''),
  );
  return joined
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/gu, ' ')
    .trim();
}

const LINK =
  /(?:https?:\/\/|www\.)\S+|\b[\p{L}\p{N}-]+\.(?:com|net|org|io|co|me|ly|gg|app|dev|info|xyz|tv|link|site|online)\b/iu;
// Matched per word and anchored, with classes that cannot overlap, so a long
// run of one character costs linear time, not quadratic.
const EMAIL_WORD = /^[^@]+@[^@.]+(?:\.[^@.]+)+$/u;
const hasEmail = (text: string) => text.split(' ').some((word) => EMAIL_WORD.test(word));
// Seven or more digits, allowing the usual separators (spaces, dots,
// dashes, brackets, a leading plus) between them. A single pass, so no input
// can make it slow.
const PHONE_SEPARATORS = new Set([' ', '\t', '\n', '(', ')', '.', '-', '+']);
function hasPhone(text: string): boolean {
  let digits = 0;
  for (const ch of text) {
    if (ch >= '0' && ch <= '9') {
      digits += 1;
      if (digits >= 7) return true;
    } else if (!PHONE_SEPARATORS.has(ch)) {
      digits = 0;
    }
  }
  return false;
}

/** Runs every rule and says the first one the text breaks. */
export function checkText(input: string, rules: TextRules = {}): TextCheck {
  const {
    maxLength = 200,
    maxWords = Number.POSITIVE_INFINITY,
    blocklist,
    allowLinks = false,
    allowContact = false,
  } = rules;
  const text = tidyText(input);
  if (!text) return { ok: false, reason: 'empty' };
  if (visibleLength(text) > maxLength) return { ok: false, reason: 'too-long' };
  if (!allowContact && (hasEmail(text) || hasPhone(text))) return { ok: false, reason: 'contact' };
  if (!allowLinks && LINK.test(text)) return { ok: false, reason: 'link' };
  if (blocklist && blocklist.length > 0 && isBlocked(text, blocklist)) return { ok: false, reason: 'blocked' };
  if (wordsOf(text).length > maxWords) return { ok: false, reason: 'too-many-words' };
  return { ok: true, text };
}

/**
 * True when any whole word, or run of words, of `text` is on the list.
 * Letters spelled out with spaces ("b a d") fold back into a word anywhere in
 * the text. Other splits ("ba d") are caught only when they are the whole
 * text, so a moderation queue still matters for open text.
 */
export function isBlocked(text: string, blocklist: readonly string[]): boolean {
  const hay = ` ${foldText(text)} `;
  const squeezed = ` ${hay.replace(/\s+/g, '')} `;
  for (const raw of blocklist) {
    const needle = foldText(raw);
    if (!needle) continue;
    if (hay.includes(` ${needle} `)) return true;
    // The whole text is the word with its spaces taken out ("ba d").
    if (!needle.includes(' ') && squeezed === ` ${needle} `) return true;
  }
  return false;
}

/**
 * @interlace/ui — text-safety-model
 *
 * The checks a short piece of typed text passes before a room shows it on a
 * shared screen: a word for a word cloud, a question for a Q&A board, a line
 * for an open wall. Pure, so the phone that sends it and the server that
 * receives it run the same rules and agree on the reason.
 *
 * ## What it checks, in order
 *
 *   1. empty            nothing left after trimming
 *   2. too-long         more than `maxLength` characters (counted as the reader sees them)
 *   3. contact          an email address or a phone number
 *   4. link             a URL or a bare domain
 *   5. blocked          a word on the consumer's `blocklist`
 *   6. too-many-words   more than `maxWords` words
 *
 * `blocked` comes before the word count, so "b a d" is refused for what it
 * says, not for having three words.
 *
 * Interlace ships no word list of its own: what is unwelcome depends on the
 * room, its language and its audience, so the consumer passes one. Matching
 * runs on `foldText`, which lowercases, strips accents and marks, folds the
 * common letter swaps (0→o, 1→i, 3→e, 4→a, 5→s, 7→t, @→a, $→s) and joins
 * letters spelled out with spaces or dots ("b a d" → "bad"), so the usual
 * dodges do not get through. Whole words only: a blocked word inside a
 * longer, innocent word is not a match.
 *
 * A filter is one layer, never the only one. Rooms that show typed text to
 * a crowd should also hold it for review (see `question-board-model`).
 */

import { foldText, tidyText } from '@/components/ui/games/text-safety-model';

/**
 * @interlace/ui — word-cloud-model
 *
 * Turns the words a room sent into the cloud it sees: grouped, counted,
 * ranked and sized. Pure, so a server can build the same cloud for a recap
 * page or an export.
 *
 * ## Grouping
 *
 * Two entries are the same word when their `foldText` forms match, so
 * "Coffee", "coffee " and "COFFEE" land on one word. The cloud shows the
 * spelling most people used (ties go to the first one sent). Stop words the
 * consumer passes are dropped; Interlace ships none, because they depend on
 * the language of the room.
 *
 * ## Size
 *
 * `step` is 1 to `steps` (default 5), on a square-root scale of the count, so
 * one runaway word does not shrink every other word to a dot. `share` is the
 * word's part of all words, 0 to 1.
 *
 * ## Order
 *
 * `words` come back in rank order (most first, then the first sent), the
 * order a screen reader hears. `cloudOrder` gives each rank a visual place:
 * the biggest words on a middle band, centre-out, with the smaller words
 * on bands above and below, which is how a cloud is read at a glance.
 */

export interface CloudEntry {
  /** What was typed. */
  text: string;
  /** Who sent it, so `mine` can be marked. Optional. */
  by?: string;
}

export interface CloudWord {
  /** Stable id for the word (its folded form). */
  key: string;
  /** The spelling to show. */
  text: string;
  count: number;
  /** 0 to 1, of all counted words. */
  share: number;
  /** 1 (smallest) to `steps`. */
  step: number;
  /** 0 for the most-sent word. */
  rank: number;
  /** True when `viewer` sent it. */
  mine: boolean;
}

export interface CloudOptions {
  /** Keep at most this many words, the most-sent first. @default 50 */
  max?: number;
  /** Size steps. @default 5 */
  steps?: number;
  /** Words to leave out, matched on their folded form. */
  stopwords?: readonly string[];
  /** Marks the words this sender sent. */
  viewer?: string;
}

export interface Cloud {
  words: CloudWord[];
  /** Every counted word, including those past `max`. */
  total: number;
  /** Distinct words, including those past `max`. */
  distinct: number;
}

export function buildCloud(entries: readonly (CloudEntry | string)[], options: CloudOptions = {}): Cloud {
  const { max = 50, steps = 5, stopwords, viewer } = options;
  const stop = new Set((stopwords ?? []).map(foldText));
  const groups = new Map<string, { first: number; count: number; spellings: Map<string, number>; mine: boolean }>();
  let total = 0;

  entries.forEach((entry, i) => {
    const e = typeof entry === 'string' ? { text: entry } : entry;
    const text = tidyText(e.text);
    const key = foldText(text);
    if (!key || stop.has(key)) return;
    total++;
    let g = groups.get(key);
    if (!g) {
      g = { first: i, count: 0, spellings: new Map(), mine: false };
      groups.set(key, g);
    }
    g.count++;
    g.spellings.set(text, (g.spellings.get(text) ?? 0) + 1);
    if (viewer !== undefined && e.by === viewer) g.mine = true;
  });

  const ranked = [...groups.entries()].sort((a, b) => b[1].count - a[1].count || a[1].first - b[1].first);
  const kept = ranked.slice(0, Math.max(0, max));
  const top = kept[0]?.[1].count ?? 0;
  const lowest = kept[kept.length - 1]?.[1].count ?? 0;
  const span = Math.sqrt(top) - Math.sqrt(lowest);
  const n = Math.max(1, Math.floor(steps));

  const words = kept.map(([key, g], rank): CloudWord => {
    let best = '';
    let bestN = 0;
    for (const [s, c] of g.spellings) {
      if (c > bestN) {
        best = s;
        bestN = c;
      }
    }
    // All kept words sent equally often: they share the top step.
    const t = span > 0 ? (Math.sqrt(g.count) - Math.sqrt(lowest)) / span : 1;
    return {
      key,
      text: best,
      count: g.count,
      // A kept word was counted, so `total` is at least 1.
      share: g.count / total,
      step: 1 + Math.round(t * (n - 1)),
      rank,
      mine: g.mine,
    };
  });

  return { words, total, distinct: groups.size };
}

/**
 * The visual slot for each rank among `n` words: rank 0 in the middle, then
 * alternating to either side, so the biggest words sit in the centre of a
 * wrapped, centred line of words.
 *
 *   centerOut(5) → [2, 3, 1, 4, 0]   (rank 0 at slot 2, rank 1 at slot 3, …)
 */
export function centerOut(n: number): number[] {
  const mid = Math.floor((n - 1) / 2);
  return Array.from({ length: Math.max(0, n) }, (_, rank) => {
    const off = Math.ceil(rank / 2);
    return rank % 2 === 1 ? mid + off : mid - off;
  });
}

/** The band a word sits on, and its CSS `order`, from `cloudOrder`. */
export interface CloudPlace {
  band: 'above' | 'middle' | 'below';
  order: number;
}

/** CSS `order` of the break before the middle band and the one after it. */
export const CLOUD_BREAKS = [999, 1999] as const;

/**
 * Where each rank goes among `n` words. The top `middle` ranks (default: a
 * third, at least 1 and at most 7) sit centre-out on the middle band; the
 * rest alternate above and below it, each band centre-out too, so the
 * small words frame the big ones.
 */
export function cloudOrder(n: number, middle?: number): CloudPlace[] {
  const count = Math.max(0, n);
  const mid = Math.min(count, middle ?? Math.min(7, Math.max(1, Math.ceil(count / 3))));
  const rest = count - mid;
  const aboveN = Math.ceil(rest / 2);
  const slotsMid = centerOut(mid);
  const slotsAbove = centerOut(aboveN);
  const slotsBelow = centerOut(rest - aboveN);
  return Array.from({ length: count }, (_, rank): CloudPlace => {
    if (rank < mid) return { band: 'middle', order: 1000 + (slotsMid[rank] as number) };
    const r = rank - mid;
    const i = Math.floor(r / 2);
    return r % 2 === 0
      ? { band: 'above', order: slotsAbove[i] as number }
      : { band: 'below', order: 2000 + (slotsBelow[i] as number) };
  });
}
